package village.vale;
import java.util.*;import net.minecraft.item.*;import net.minecraft.entity.player.*;import net.minecraft.world.World;import net.minecraft.nbt.NBTTagCompound;import net.minecraft.util.*;import net.minecraft.util.text.*;import net.minecraft.advancements.*;import net.minecraftforge.event.RegistryEvent;import net.minecraftforge.fml.common.Mod;import net.minecraftforge.fml.common.eventhandler.SubscribeEvent;import net.minecraftforge.fml.common.gameevent.TickEvent;
/** Real server-awarded original advancement records; no arbitrary rewards or client supplied criteria. */
@Mod.EventBusSubscriber(modid=ValeOrders.ID)
public final class OriginalMilestones {
 private OriginalMilestones(){}
 public static final String[] KEYS={"first_oath","first_contract","trusted_runner","field_adept","field_veteran","field_master","dungeon_1","dungeon_2","dungeon_3","dungeon_4","dungeon_5","resonance_cairnroot","resonance_glasschime","resonance_shoalglass","resonance_kilnback","resonance_reedrunner","resonance_bellbloom","resonance_auric_skimmer","resonance_hushvault","resonance_stormloom","first_keeper","first_resonance"};
 private static final String[] PROFILES={"cairnroot","glasschime","shoalglass","kilnback","reedrunner","bellbloom","auric_skimmer","hushvault","stormloom"};
 private static final int[][] SITES={{30976,69,30848},{31488,137,30848},{32000,161,30848},{32512,145,30848},{33024,151,30848}};
 static String title(String key){StringBuilder s=new StringBuilder();for(String p:key.split("_")){if(s.length()>0)s.append(' ');s.append(Character.toUpperCase(p.charAt(0))).append(p.substring(1));}return s.toString();}
 public static void register(RegistryEvent.Register<Item> e){for(int i=0;i<KEYS.length;i++){final int id=i;Gear.add(e,"chronicle_"+KEYS[i],new Item(){@Override public String getItemStackDisplayName(ItemStack s){return title(KEYS[id])+" Chronicle";}@Override public ActionResult<ItemStack> onItemRightClick(World w,EntityPlayer p,EnumHand hand){if(!w.isRemote&&p instanceof EntityPlayerMP){check((EntityPlayerMP)p);p.sendStatusMessage(new TextComponentString(title(KEYS[id])+": "+(PlayerState.data(p).getCompoundTag("originalMilestones").getBoolean(KEYS[id])?"recorded":"not yet recorded")+". /vale missions shows your current work."),false);}return new ActionResult<>(EnumActionResult.SUCCESS,p.getHeldItem(hand));}}.setMaxStackSize(1));}}
 public static boolean eligible(EntityPlayerMP p,int index,village.vale.armor.ArmorProfile armor){NBTTagCompound s=PlayerState.data(p);if(index==20)return s.getCompoundTag("dossier").getInteger("valeorders:trial_keeper")>0||s.getCompoundTag("dossier").getInteger("valeencounters:boss")>0;if(index==21)return armor!=null;if(index==0)return !s.getString("starterOrder").isEmpty();if(index==1)return s.getInteger("missionsCompleted")>=1;if(index==2)return s.getInteger("missionsCompleted")>=3;if(index>=3&&index<=5)return PlayerState.level(p)>=new int[]{5,10,15}[index-3];if(index>=6&&index<=10){int[] at=SITES[index-6];return p.dimension==0&&p.getDistanceSq(at[0],at[1],at[2])<=2500;}return index>=11&&index<20&&armor!=null&&armor.key.equals(PROFILES[index-11]);}
 public static void check(EntityPlayerMP p){NBTTagCompound saved=PlayerState.data(p),records=saved.getCompoundTag("originalMilestones");village.vale.armor.ArmorProfile armor=OriginalArmorRegistry.full(p);boolean changed=false;for(int i=0;i<KEYS.length;i++)if(!records.getBoolean(KEYS[i])&&eligible(p,i,armor)){records.setBoolean(KEYS[i],true);changed=true;Advancement advancement=p.getServer().getAdvancementManager().getAdvancement(new ResourceLocation(ValeOrders.ID,"chronicle/"+KEYS[i]));if(advancement!=null)p.getAdvancements().grantCriterion(advancement,"recorded");}if(changed){saved.setTag("originalMilestones",records);Adventures.save(p);}}
 @SubscribeEvent public static void tick(TickEvent.PlayerTickEvent e){if(e.phase==TickEvent.Phase.END&&!e.player.world.isRemote&&e.player instanceof EntityPlayerMP&&e.player.isEntityAlive()&&e.player.ticksExisted%40==0)check((EntityPlayerMP)e.player);}
}
